-- Тексты вместо заглушек [УТОЧНИТЬ] в уже созданной базе. Меняется только то, что ещё равно старой заглушке:
-- правки из кабинета не затираются. Обратная миграция возвращает заглушки так же — только там, где текст не меняли.

-- +goose Up
UPDATE settings SET value = jsonb_set(value, '{why,0,text}', to_jsonb('По залу бегают маленькие собаки: можно погладить, поиграть или просто смотреть, как они спят у окна. Собака спит или ушла в домик — значит, отдыхает, не будим. Угощать их можно только лакомством от бариста.'::text)), updated_at = now()
WHERE key = 'content' AND value #>> '{why,0,text}' = 'По залу бегают маленькие собаки: можно погладить, поиграть или просто смотреть, как они спят у окна. [УТОЧНИТЬ: сколько собак и какие]';

UPDATE settings SET value = jsonb_set(value, '{why,1,text}', to_jsonb('Берите собаку с собой — ей здесь рады так же, как вам. В зале держите её на поводке и рядом со столиком, на стулья и столы не пускаем. Миску с водой принесём сами. Если собака волнуется среди других — выберите столик у входа, там спокойнее.'::text)), updated_at = now()
WHERE key = 'content' AND value #>> '{why,1,text}' = 'Берите собаку с собой — ей здесь рады так же, как вам. [УТОЧНИТЬ: правила для гостей с собаками]';

UPDATE settings SET value = jsonb_set(value, '{dogs}', '[
  {"name": "Пончик", "about": "шпиц — первым бежит встречать у двери и знает, у кого в кармане лакомство.", "photo": "/img/dog-green.jpg"},
  {"name": "Ириска", "about": "той-пудель — любит колени гостей и может проспать на них весь капучино.", "photo": "/img/dog-yellow.jpg"},
  {"name": "Бублик", "about": "корги — главный по мячику. Бросите один раз — придётся играть до закрытия.", "photo": "/img/dog-red.jpg"},
  {"name": "Кнопка", "about": "чихуахуа — сначала смотрит издалека, а потом выбирает самый тёплый плед.", "photo": "/img/dog-mint.jpg"}
]'::jsonb), updated_at = now()
WHERE key = 'content' AND value -> 'dogs' = '[
  {"name": "", "about": "", "photo": "/img/dog-green.jpg"}, {"name": "", "about": "", "photo": "/img/dog-yellow.jpg"},
  {"name": "", "about": "", "photo": "/img/dog-red.jpg"}, {"name": "", "about": "", "photo": "/img/dog-mint.jpg"}
]'::jsonb;

UPDATE settings SET value = jsonb_set(value, '{how_to_get}', to_jsonb('Вход с улицы Сарьяна. Ближайшие остановки — «29-я линия» и «35-я линия». Рядом «Пятёрочка» и «Фасоль». Машину можно оставить вдоль улицы.'::text)), updated_at = now()
WHERE key = 'content' AND coalesce(value ->> 'how_to_get', '') = '';

UPDATE menu_items SET name = 'Лапа на льду', description = 'Холодный латте: двойной эспрессо, молоко, солёная карамель и много льда.', updated_at = now()
WHERE name = 'Авторский напиток' AND description = '[УТОЧНИТЬ: название и состав]';

UPDATE events SET description = 'Знакомимся, болтаем о питомцах за кофе, собаки играют в зале. В программе — знакомство, свободная игра собак и обмен советами. Вход свободный, кофе — по меню. Можно со своей собакой на поводке.', updated_at = now()
WHERE description = 'Знакомимся, болтаем о питомцах за кофе, собаки играют в зале. [УТОЧНИТЬ: программа и цена]';
UPDATE events SET description = 'Бариста покажет, как нарисовать сердце и мордочку собаки. Полтора часа практики: взбиваем молоко, рисуем и пьём свой латте. Опыт не нужен. Участие — 700 ₽.', updated_at = now()
WHERE description = 'Бариста покажет, как нарисовать сердце и мордочку собаки. [УТОЧНИТЬ: цена]';
UPDATE events SET description = 'Отмечаем дни рождения собак, у которых праздник в этом месяце. Торт для собак, колпаки и общее фото. Участие — 500 ₽ за собаку с хозяином.', updated_at = now()
WHERE description = 'Торт для собак, колпаки и общее фото. [УТОЧНИТЬ: чей праздник, условия]';

